302	"#;
303	
304	        let templates = RemoteLoader::parse_templates(yaml).unwrap();
305	        assert_eq!(templates.len(), 2);
306	        assert_eq!(templates[0].name, "tool-a");
307	        assert_eq!(templates[1].name, "tool-b");
308	    }
309	
310	    #[test]
311	    fn parse_invalid_content_returns_error() {
312	        let result = RemoteLoader::parse_templates("not a template at all: [[[");
313	        assert!(result.is_err());
314	    }
315	
316	    fn make_source(url: String, kind: TemplateSourceKind) -> TemplateSourceConfig {
317	        TemplateSourceConfig {
318	            kind: Some(kind),
319	            url,
320	            git_ref: Some("main".to_string()),
321	            path: None,
322	            priority: 50,
