329	    #[test]
330	    fn loads_templates_from_git_source_root() {
331	        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
332	        let temp = TempDir::new().unwrap();
333	
334	        let template_yaml = r#"
335	name: git-tool
336	description: "Tool from a git remote"
337	category: tools
338	step:
339	  command: git-tool run
340	"#;
341	        let bare = create_bare_repo_with_templates(temp.path(), &[("git-tool.yml", template_yaml)]);
342	
