351	
352	        let loader = RemoteLoader::new(&sources, &http, &git, &cache).unwrap();
353	        let template = loader
354	            .get("git-tool")
355	            .expect("git-tool template should be loaded from the git source");
356	        assert_eq!(template.name, "git-tool");
357	        assert_eq!(template.description, "Tool from a git remote");
358	    }
359	
360	    #[test]
361	    fn git_source_loads_only_from_configured_subdir() {
362	        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
363	        let temp = TempDir::new().unwrap();
364	
365	        let included_yaml = r#"
366	name: included-tool
367	description: "Included via path"
368	category: tools
369	step:
370	  command: included
371	"#;
372	        let excluded_yaml = r#"
373	name: excluded-tool
374	description: "Outside the configured path"
375	category: tools
376	step:
377	  command: excluded
