    #[test]
    fn concurrent_read_write_never_sees_corrupt_metadata() {
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::sync::Arc;
        use std::thread;
        use std::time::Duration;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        // Pre-populate the cache entry so readers have something to read.
        store
            .store("http:test", "contended", "initial", 3600)
            .unwrap();

        let done = Arc::new(AtomicBool::new(false));
        let corruption_seen = Arc::new(AtomicBool::new(false));

        // Spawn writer threads that overwrite the same entry with varying content.
        let writers: Vec<_> = (0..4)
            .map(|i| {
                let store = Arc::clone(&store);
                let done = Arc::clone(&done);
                thread::spawn(move || {
                    let mut iteration = 0u64;
                    while !done.load(Ordering::Relaxed) {
                        let content = format!("writer-{}-iter-{}", i, iteration);
                        let _ = store.store("http:test", "contended", &content, 3600);
                        iteration += 1;
                    }
                })
            })
            .collect();

        // Spawn reader threads that validate metadata/content consistency.
        let readers: Vec<_> = (0..4)
            .map(|_| {
                let store = Arc::clone(&store);
                let done = Arc::clone(&done);
                let corruption_seen = Arc::clone(&corruption_seen);
                thread::spawn(move || {
                    while !done.load(Ordering::Relaxed) {
                        if let Ok(Some(entry)) = store.load("http:test", "contended") {
                            // Metadata must parse correctly (non-corrupt JSON).
                            // Content length must match metadata size_bytes.
                            if let Ok(content) = store.read_content(&entry) {
                                if entry.metadata.size_bytes != content.len() as u64 {
                                    corruption_seen.store(true, Ordering::Relaxed);
                                    return;
                                }
                            }
                        }
                    }
                })
            })
            .collect();

        thread::sleep(Duration::from_millis(200));
        done.store(true, Ordering::Relaxed);

        for w in writers {
            w.join().unwrap();
        }
        for r in readers {
            r.join().unwrap();
        }

        assert!(
            !corruption_seen.load(Ordering::Relaxed),
            "Reader saw metadata/content size mismatch — cache was corrupted by concurrent writes"
        );
    }
}

