        for entry in std::fs::read_dir(temp.path()).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            assert!(
                !path.extension().is_some_and(|e| e == "tmp"),
                "temp file left behind: {:?}",
                path
            );
        }
    }
}

