    }

    #[test]
    fn read_content() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "hello world", 3600)
            .unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "hello world");
    }

    #[test]
    fn load_nonexistent_returns_none() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let result = store.load("http:test", "nonexistent").unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn remove_entry() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let removed = store.remove("http:test", "template1").unwrap();
        assert!(removed);

        let loaded = store.load("http:test", "template1").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn remove_nonexistent_returns_false() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let removed = store.remove("http:test", "nonexistent").unwrap();
        assert!(!removed);
    }

    #[test]
    fn list_entries() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 2);
    }

    #[test]
    fn clear_cache() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let cleared = store.clear().unwrap();
        assert_eq!(cleared, 2);

        let entries = store.list().unwrap();
        assert!(entries.is_empty());
    }

    #[test]
    fn total_size_calculation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("http:test", "t1", "12345", 3600).unwrap(); // 5 bytes
        store.store("http:test", "t2", "1234567890", 3600).unwrap(); // 10 bytes

        let total = store.total_size().unwrap();
        assert_eq!(total, 15);
    }

    #[test]
    fn content_path_is_deterministic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template");
        let path2 = store.content_path("http:test", "template");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_writes_do_not_corrupt_cache() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                thread::spawn(move || {
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        // After all concurrent writes, the cache must be consistent:
        // metadata must exist, content must be readable, and they must match.
        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();
        assert!(content.starts_with("content-from-thread-"));
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }

    #[test]
    fn concurrent_writes_to_different_entries_all_succeed() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                thread::spawn(move || {
                    let name = format!("template-{}", i);
                    let content = format!("content-{}", i);
                    store
                        .store("http:test", &name, &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        // All entries should be readable and consistent.
        for i in 0..10 {
            let name = format!("template-{}", i);
            let expected_content = format!("content-{}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected_content);
        }
    }

    #[test]
    fn no_temp_files_remain_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        // No .tmp files should remain in the cache directory.
        for entry in std::fs::read_dir(temp.path()).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            assert!(
                !path.extension().is_some_and(|e| e == "tmp"),
                "temp file left behind: {:?}",
                path
            );
        }
    }

    #[test]
    fn concurrent_read_write_never_sees_corrupt_metadata() {
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::sync::Arc;
        use std::thread;
        use std::time::Duration;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        // Pre-populate the cache entry so readers have something to read.
        store
            .store("http:test", "contended", "initial", 3600)
            .unwrap();

        let done = Arc::new(AtomicBool::new(false));
        let corruption_seen = Arc::new(AtomicBool::new(false));

        // Spawn writer threads that overwrite the same entry with varying content.
        let writers: Vec<_> = (0..4)
            .map(|i| {
                let store = Arc::clone(&store);
                let done = Arc::clone(&done);
                thread::spawn(move || {
                    let mut iteration = 0u64;
                    while !done.load(Ordering::Relaxed) {
                        let content = format!("writer-{}-iter-{}", i, iteration);
                        let _ = store.store("http:test", "contended", &content, 3600);
                        iteration += 1;
                    }
                })
            })
            .collect();

        // Spawn reader threads that validate metadata/content consistency.
        let readers: Vec<_> = (0..4)
            .map(|_| {
                let store = Arc::clone(&store);
                let done = Arc::clone(&done);
                let corruption_seen = Arc::clone(&corruption_seen);
                thread::spawn(move || {
                    while !done.load(Ordering::Relaxed) {
                        if let Ok(Some(entry)) = store.load("http:test", "contended") {
                            // Metadata must parse correctly (non-corrupt JSON).
                            // Content length must match metadata size_bytes.
                            if let Ok(content) = store.read_content(&entry) {
                                if entry.metadata.size_bytes != content.len() as u64 {
                                    corruption_seen.store(true, Ordering::Relaxed);
                                    return;
                                }
                            }
                        }
                    }
                })
            })
            .collect();

        thread::sleep(Duration::from_millis(200));
        done.store(true, Ordering::Relaxed);

        for w in writers {
            w.join().unwrap();
        }
        for r in readers {
            r.join().unwrap();
        }

        assert!(
            !corruption_seen.load(Ordering::Relaxed),
            "Reader saw metadata/content size mismatch — cache was corrupted by concurrent writes"
        );
    }
}

