/// Write data to a file atomically using write-to-temp-then-rename.
///
/// Guarantees that readers never see a partially written file: the rename
/// is atomic on POSIX systems, so the destination either contains the old
/// content or the complete new content.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let counter = TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
    let temp_name = format!(
        ".tmp.{}.{}",
        std::process::id(),
        counter,
    );
    let temp_path = path.with_file_name(temp_name);

    fs::write(&temp_path, data).with_context(|| {
        format!("Failed to write temp file {:?}", temp_path)
    })?;

    fs::rename(&temp_path, path).with_context(|| {
        format!("Failed to rename {:?} to {:?}", temp_path, path)
    })?;

    Ok(())
}

