/// Load a cached entry's metadata.
pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
    let meta_path = self.metadata_path(source_id, template_name);

    if !meta_path.exists() {
        return Ok(None);
    }

    let json = match fs::read_to_string(&meta_path) {
        Ok(j) => j,
        Err(_) => return Ok(None),
    };
    let entry: CacheEntry = match serde_json::from_str(&json) {
        Ok(e) => e,
        Err(_) => return Ok(None),
    };

    Ok(Some(entry))
}

/// Read the cached content, validating consistency with metadata.
///
/// Returns an error if the content file is missing or if its length
/// does not match the metadata's `size_bytes` (indicating a concurrent
/// write race). Callers should treat errors as a cache miss.
pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
    let content = fs::read_to_string(&entry.content_path).with_context(|| {
        format!(
            "Failed to read cached content from {:?}",
            entry.content_path
        )
    })?;

    if content.len() as u64 != entry.metadata.size_bytes {
        anyhow::bail!("Cache content/metadata mismatch (concurrent write race)");
    }

    Ok(content)
}

