9	use super::entry::CacheEntry;
10	
11	/// Global counter for generating unique temp file names.
12	static TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);
13	
14	/// Storage for cached templates.
15	pub struct CacheStore {
16	    /// Root directory for cache.
17	    root: PathBuf,
18	}
19	
20	impl CacheStore {
21	    /// Create a new cache store.
22	    pub fn new(root: impl Into<PathBuf>) -> Self {
23	        Self { root: root.into() }
24	    }
25	
26	    /// Get the cache root directory.
27	    pub fn root(&self) -> &Path {
28	        &self.root
29	    }
30	
31	    /// Ensure the cache directory exists.
32	    fn ensure_dir(&self) -> Result<()> {
33	        fs::create_dir_all(&self.root)
34	            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
35	    }
36	
37	    /// Get the path for storing an entry's content.
38	    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
39	        let key = format!("{}:{}", source_id, template_name);
40	        let hash = Sha256::digest(key.as_bytes());
41	        let hash_str = hex::encode(&hash[..16]);
42	        self.root.join(hash_str)
43	    }
44	
45	    /// Get the metadata file path for an entry.
46	    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
47	        self.content_path(source_id, template_name)
48	            .with_extension("meta.json")
49	    }
50	
51	    /// Store content and return a cache entry.
52	    ///
53	    /// Uses atomic writes (write to temp file, then rename) to prevent
54	    /// corruption when multiple installations run concurrently.
55	    pub fn store(
56	        &self,
57	        source_id: &str,
58	        template_name: &str,
59	        content: &str,
60	        ttl_seconds: u64,
61	    ) -> Result<CacheEntry> {
62	        self.ensure_dir()?;
63	
64	        let content_path = self.content_path(source_id, template_name);
65	        atomic_write(&content_path, content.as_bytes())?;
66	
67	        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
68	            .with_size(content.len() as u64);
69	
70	        self.save_metadata(&entry)?;
71	
72	        Ok(entry)
73	    }
74	
75	    /// Load a cached entry's metadata.
76	    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
77	        let meta_path = self.metadata_path(source_id, template_name);
78	
79	        if !meta_path.exists() {
80	            return Ok(None);
